function execute_list_airport_ground_transport_drivers(params) {
  try {
    const drivers = [
      { id: 1, name: "John Doe", vehicleType: "Van", licenseNumber: "ABC123" },
      { id: 2, name: "Jane Smith", vehicleType: "Truck", licenseNumber: "XYZ789" },
      { id: 3, name: "Marta Alvarez", vehicleType: "Car", licenseNumber: "LMN456" }
    ];
    return { success: true, result: drivers };
  } catch (e) {
    return { success: false, error: e.message };
  }
}

export_airport_ground_transport_drivers.code:
function execute_export_airport_ground_transport_drivers(params) {
  if (!params || !Array.isArray(params.input)) {
    return { success: false, error: "Invalid or missing 'input' array" };
  }
  var groundDrivers = params.input.filter(function(driver) {
    return driver.transportType === "ground";
  });
  return { success: true, result: JSON.stringify(groundDrivers) };
}
